import type { CourseText } from "./course";

export type CourseMedia = {
  mindMap?: {
    path: string;
    title: CourseText;
    caption: CourseText;
    outline: CourseText[];
  };
  noteFigures?: Array<{
    path: string;
    sectionId: string;
    title: CourseText;
    caption: CourseText;
    alt: CourseText;
  }>;
  textbookFigures?: Array<{
    path: string;
    sectionId: string;
    figureRef: string;
    page: number;
    title: CourseText;
    caption: CourseText;
    check: CourseText;
    alt: CourseText;
  }>;
  textbookAtlas: Array<{
    title: CourseText;
    relationship: CourseText;
    steps: CourseText[];
  }>;
};

const t = (en: string, zh: string): CourseText => ({ en, zh });

const textbookFigure = (
  file: string,
  sectionId: string,
  figureRef: string,
  page: number,
  titleEn: string,
  titleZh: string,
  captionEn: string,
  captionZh: string,
  checkEn: string,
  checkZh: string,
) => ({
  path: `textbook/chapter-01/${file}`,
  sectionId,
  figureRef,
  page,
  title: t(titleEn, titleZh),
  caption: t(captionEn, captionZh),
  check: t(checkEn, checkZh),
  alt: t(`${figureRef}: ${titleEn}`, `${figureRef}：${titleZh}`),
});

const textbookFigureForChapter = (
  chapter: number,
  file: string,
  sectionId: string,
  figureRef: string,
  page: number,
  titleEn: string,
  titleZh: string,
  captionEn: string,
  captionZh: string,
  checkEn: string,
  checkZh: string,
) => ({
  path: `textbook/chapter-${String(chapter).padStart(2, "0")}/${file}`,
  sectionId,
  figureRef,
  page,
  title: t(titleEn, titleZh),
  caption: t(captionEn, captionZh),
  check: t(checkEn, checkZh),
  alt: t(`${figureRef}: ${titleEn}`, `${figureRef}：${titleZh}`),
});

const map = (path: string, en: string, zh: string, outline: CourseText[]) => ({
  path,
  title: t(en, zh),
  caption: t(
    "Personal study map supplied by the learner. Use it for retrieval after completing the lesson, and verify any conflicting wording against the fifth edition.",
    "学习者提供的个人思维导图。请先学习英文主课程，再用它主动回忆；如有冲突，以第五版英文内容为准。",
  ),
  outline,
});

